<?php foreach(array_merge([null],$services) as $service):?><details><summary><?=me($service['name']??__('manor.new_service'))?></summary><form method="post"><?=csrf()?><input type="hidden" name="action" value="service"><input type="hidden" name="service_id" value="<?=me($service['id']??'')?>"><?=field('name',__('manor.service_name'),$service['name']??'')?><label><?=me(__('manor.description'))?><textarea name="description"><?=me($service['description']??'')?></textarea></label><?=field('amount',__('manor.amount').' · '.$settings['currency'],$service['amount']??'0.00')?><?=field('tax_bps',__('manor.tax_basis_points'),$service['tax_bps']??0,'number')?><label class="check"><input type="checkbox" name="refundable" value="1" <?=($service['refundable']??false)?'checked':''?>><?=me(__('manor.refundable_deposit'))?></label><label class="check"><input type="checkbox" name="enabled" value="1" <?=!$service||$service['enabled']?'checked':''?>><?=me(__('manor.enabled'))?></label><button><?=me(__('manor.save_service'))?></button></form></details><?php endforeach?>
